        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Long monochrome runs on the boundary are guide bars.
    bars = {"top": [], "bottom": [], "left": [], "right": []}
    for side in bars:
        line = (grid[0] if side == "top" else grid[h - 1] if side == "bottom"
                else [grid[r][0] for r in range(h)] if side == "left"
                else [grid[r][w - 1] for r in range(h)])
        i = 0
        while i < len(line):
            if line[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(line) and line[j] == line[i]:
                j += 1
            if j - i >= 2:
                bars[side].append((line[i], i, j))
            i = j

    edge_colors = {color for runs in bars.values() for color, _, _ in runs}
    markers = [v for v in counts if v != background and v not in edge_colors]
    if not markers:
        return out
    # In these tasks the non-background, non-bar color is the projected color.
    marker_color = max(markers, key=lambda v: counts[v])

    def cast(side, pos):
        if side == "top":
            cells = ((r, pos) for r in range(1, h))
        elif side == "bottom":
            cells = ((r, pos) for r in range(h - 2, -1, -1))
        elif side == "left":
            cells = ((pos, c) for c in range(1, w))
        else:
            cells = ((pos, c) for c in range(w - 2, -1, -1))
        for r, c in cells:
            value = grid[r][c]
            if value == marker_color:
                out[r][c] = 4
                break
            if value == background:
                out[r][c] = marker_color
            else:
                break

    for side, runs in bars.items():
        for _bar_color, start, end in runs:
            for pos in range(start, end):
                cast(side, pos)
    return out

